class ApronFarmerFace extends StatelessWidget {
  final ApronFarmerFaceExpression expression;
  final double? width;
  final double? height;
  final ColorMapper? colorMapper;

  const ApronFarmerFace({
    required this.expression,
    this.width,
    this.height,
    this.colorMapper,
    super.key,
  });

  @override
  Widget build(BuildContext context) {
    late String svgString;
    switch (expression) {
      case ApronFarmerFaceExpression.surprised:
        svgString = _farmerFaceSurprised;
      case ApronFarmerFaceExpression.worry:
        svgString = _farmerFaceWorry;
      case ApronFarmerFaceExpression.smile:
        svgString = _farmerFaceSmile;
    }
    return SvgPicture.string(
      svgString,
      height: height,
      width: width,
      colorMapper: colorMapper,
    );
  }
}
